// Write packages/core/src/idea-card-icons.ts: the pictograms an Idea card may draw with
// <i class="wb-icon" data-icon="…">, taken from the lucide icons the web app already depends on
// (ISC licence, kept in the generated file). Run it after changing NAMES or upgrading lucide-react:
//
//   node scripts/gen-card-icons.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** The set, chosen for what product concepts and outcomes draw: people, work, places, time, money, signals. */
const NAMES = [
  "user", "users", "user-check", "user-round", "users-round", "baby", "handshake", "smile", "frown", "heart",
  "briefcase", "building-2", "store", "house", "factory", "school", "hospital", "stethoscope", "graduation-cap",
  "truck", "car", "plane", "ship", "map-pin", "route", "milestone", "footprints", "globe", "compass", "mountain",
  "calendar", "calendar-check", "calendar-days", "clock", "timer", "hourglass", "sun", "moon", "coffee",
  "smartphone", "laptop", "message-square", "mail", "send", "bell", "megaphone", "mic", "headphones", "camera",
  "file-text", "clipboard-list", "list-checks", "sheet", "notebook-pen", "book-open", "pen-line", "kanban", "layout-grid",
  "layers", "database", "cloud", "search", "filter", "sliders-horizontal", "cog", "workflow", "git-branch", "split", "merge", "shuffle",
  "zap", "rocket", "lightbulb", "target", "flag", "gauge", "eye", "sparkles",
  "shield-check", "lock", "key-round", "link", "puzzle", "inbox", "package",
  "wrench", "hammer", "leaf", "spray-can", "paintbrush", "scissors", "utensils",
  "shopping-cart", "credit-card", "receipt", "banknote", "chart-line", "chart-column", "trending-up", "trending-down",
  "check", "x", "circle-alert", "triangle-alert", "repeat", "refresh-cw", "undo-2", "arrow-right", "arrow-down", "corner-down-right", "quote",
];

const dir = new URL("../apps/web/node_modules/lucide-react/", import.meta.url);
const version = JSON.parse(readFileSync(new URL("package.json", dir), "utf8")).version;
const attr = (k, v) => ` ${k}="${String(v).replace(/"/g, "&quot;")}"`;
const icons = {};
for (const name of NAMES) {
  // An alias's module only re-exports the icon it names; follow it to the module that holds the data.
  let file = `${name}.mjs`;
  for (let alias; (alias = /export \{ default \} from '\.\/([\w-]+\.mjs)'/.exec(readFileSync(new URL(`dist/esm/icons/${file}`, dir), "utf8"))); ) file = alias[1];
  const { __iconData } = await import(new URL(`dist/esm/icons/${file}`, dir).href);
  icons[name] = __iconData.node.map(([tag, a]) => `<${tag}${Object.entries(a).filter(([k]) => k !== "key").map(([k, v]) => attr(k, v)).join("")}/>`).join("");
}

const out = `/**
 * The pictograms an Idea card may draw with <i class="wb-icon" data-icon="…">: each icon's SVG
 * elements on lucide's 24-unit grid, stroked. Generated by scripts/gen-card-icons.mjs from
 * lucide-react ${version}; do not edit by hand.
 *
 * Lucide is under the ISC License: Copyright (c) Lucide Icons and Contributors. Permission to use,
 * copy, modify, and/or distribute this software for any purpose with or without fee is hereby
 * granted, provided that the above copyright notice and this permission notice appear in all
 * copies. THE SOFTWARE IS PROVIDED "AS IS" AND THE AUTHOR DISCLAIMS ALL WARRANTIES WITH REGARD TO
 * THIS SOFTWARE INCLUDING ALL IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS. IN NO EVENT SHALL
 * THE AUTHOR BE LIABLE FOR ANY SPECIAL, DIRECT, INDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES
 * WHATSOEVER RESULTING FROM LOSS OF USE, DATA OR PROFITS, WHETHER IN AN ACTION OF CONTRACT,
 * NEGLIGENCE OR OTHER TORTIOUS ACTION, ARISING OUT OF OR IN CONNECTION WITH THE USE OR PERFORMANCE
 * OF THIS SOFTWARE.
 */
export const CARD_ICONS: Readonly<Record<string, string>> = {
${Object.entries(icons).map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`).join("\n")}
};
`;
writeFileSync(fileURLToPath(new URL("../packages/core/src/idea-card-icons.ts", import.meta.url)), out);
console.log(`Wrote ${Object.keys(icons).length} icons from lucide-react ${version}.`);
